INSERT INTO page_sections (id, page_id, section_key, position, is_active, config, created_at, updated_at) VALUES ('37', '9', 'legal_section', '1', '1', '{\"title\":\"Syarat & Ketentuan Penggunaan\",\"subtitle\":\"Legal ACTiV\",\"last_updated\":\"23 February 2026\",\"contact_email\":\"sales@activ.co.id\",\"sections\":[{\"slug\":\"pengantar\",\"title\":\"Pengantar\",\"icon\":\"fa-regular fa-file-lines\",\"content\":\"Selamat datang di situs web PT Alfa Cipta Teknologi Virtual (ACTiV). Dengan mengakses atau menggunakan layanan kami, Anda setuju untuk terikat oleh Syarat dan Ketentuan ini.\"},{\"slug\":\"definisi\",\"title\":\"Definisi\",\"icon\":\"fa-regular fa-book\",\"content\":\"<ul><li><strong>ACTiV:<\\/strong> PT Alfa Cipta Teknologi Virtual sebagai penyedia layanan ICT.<\\/li><li><strong>Layanan:<\\/strong> Meliputi rental hardware, penjualan software, konsultasi IT, dan platform Accommerce.id.<\\/li><li><strong>Pengguna:<\\/strong> Individu atau korporasi yang menggunakan layanan ACTiV.<\\/li><\\/ul>\"},{\"slug\":\"layanan-ict\",\"title\":\"Layanan & Sewa Perangkat\",\"icon\":\"fa-regular fa-laptop-code\",\"content\":\"Layanan penyewaan perangkat keras mengikuti durasi kontrak yang disepakati. Pengguna bertanggung jawab penuh atas keamanan fisik perangkat selama masa sewa.\",\"callout\":\"Setiap kerusakan yang disebabkan oleh kelalaian penggunaan akan dikenakan biaya penggantian sesuai harga pasar yang berlaku.\"},{\"slug\":\"pembayaran\",\"title\":\"Transaksi & Pembayaran\",\"icon\":\"fa-regular fa-credit-card\",\"content\":\"Pembayaran dilakukan melalui saluran resmi yang ditunjuk ACTiV atau melalui platform Accommerce.id. Untuk proyek kustom, berlaku ketentuan DP 50% sebelum pengerjaan dimulai.\"},{\"slug\":\"hukum\",\"title\":\"Hukum yang Berlaku\",\"icon\":\"fa-regular fa-gavel\",\"content\":\"Syarat dan Ketentuan ini diatur oleh hukum Republik Indonesia. Perselisihan akan diselesaikan melalui musyawarah atau di Pengadilan Negeri Jakarta Selatan.\"}]}', '2026-02-23 07:51:02', '2026-02-23 07:51:02');
INSERT INTO pages (id, title, slug, type, status, is_homepage, show_breadcrumb, breadcrumb_image, parent_id, menu_order, created_at, updated_at) VALUES ('10', 'Kebijakan Privasi', 'kebijakan-privasi', 'static', 'published', '0', '1', NULL, NULL, '0', '2026-02-23 07:22:07', '2026-02-23 07:22:07');
INSERT INTO page_sections (id, page_id, section_key, position, is_active, config, created_at, updated_at) VALUES ('38', '10', 'legal_section', '1', '1', '{\"title\":\"Kebijakan Privasi\",\"subtitle\":\"Privasi Anda\",\"last_updated\":\"23 February 2026\",\"contact_email\":\"sales@activ.co.id\",\"sections\":[{\"slug\":\"informasi-dikumpulkan\",\"title\":\"Data yang Kami Kumpulkan\",\"icon\":\"fa-regular fa-database\",\"content\":\"Kami mengumpulkan data profil perusahaan dan kontak personal untuk keperluan administrasi layanan ICT dan verifikasi transaksi di Accommerce.id.\"},{\"slug\":\"penggunaan-data\",\"title\":\"Cara Kami Menggunakan Data\",\"icon\":\"fa-regular fa-shield-halved\",\"content\":\"Data Anda digunakan secara eksklusif untuk penyediaan layanan, pemrosesan pesanan, dan peningkatan kualitas solusi IT kami.\",\"callout\":\"ACTiV tidak pernah menjual data pelanggan kepada pihak ketiga mana pun.\"}]}', '2026-02-23 07:51:02', '2026-02-23 07:51:02');
