INSERT INTO page_sections (id, page_id, section_key, position, is_active, config, created_at, updated_at) VALUES ('39', '11', 'partnership_hero', '0', '1', '{\"id\":\"section-39\",\"className\":\"\",\"title\":\"Bangun Kemitraan Strategis Bersama ACTiV\",\"subtitle\":\"Kolaborasi Tanpa Batas\",\"button_text\":\"Ajukan Kemitraan\",\"button_url\":\"\",\"use_whatsapp\":true,\"button_url_rel\":\"noopener noreferrer\",\"description\":\"Bergabunglah dengan ekosistem teknologi terdepan untuk menghadirkan solusi ICT dan Edukasi yang inovatif bagi klien Anda.\"}', '2026-02-23 07:51:02', '2026-02-23 08:28:25');
INSERT INTO page_sections (id, page_id, section_key, position, is_active, config, created_at, updated_at) VALUES ('40', '11', 'partnership_details', '1', '1', '{\"id\":\"section-40\",\"className\":\"\",\"title\":\"Bagian dari Ekosistem Digital ACTiV\",\"subtitle\":\"\\ud83c\\udf10 Official Online Sales Platform\",\"description\":\"Sebagai bagian dari transformasi digital ACTiV, Accommerce.id memperluas akses pelanggan terhadap berbagai produk teknologi, perangkat keras, serta aksesori profesional melalui platform online yang terstruktur dan terpercaya.<br><br>Platform ini menjadi perpanjangan resmi layanan penjualan ACTiV untuk mendukung kebutuhan perusahaan, institusi, dan individu di seluruh Indonesia.\",\"partner_name\":\"Accommerce.id\",\"partner_logo\":\"\\/assets\\/img\\/partners\\/accommerceid.webp\",\"partner_url\":\"https:\\/\\/accommerce.id\",\"partner_description\":\"Accommerce.id merupakan platform resmi penjualan online dari PT Alfa Cipta Teknologi Virtual (ACTiV) yang menghadirkan solusi pembelian hardware dan lisensi software secara profesional, cepat, dan aman.<br><br>Dirancang sebagai marketplace resmi milik ACTiV, Accommerce memberikan kemudahan transaksi dengan sistem checkout instan serta dukungan purna jual bersertifikat.\",\"feature_title\":\"\\ud83d\\ude80 Keunggulan Platform\",\"features\":[{\"title\":\"Official Online Sales Channel\",\"text\":\"Kanal penjualan digital resmi dan terintegrasi dengan sistem ACTiV.\",\"icon\":\"fa-solid fa-shop\"},{\"title\":\"Transaksi Aman\",\"text\":\"Sistem pembayaran terpercaya dengan keamanan data terenkripsi.\",\"icon\":\"fa-solid fa-lock\"},{\"title\":\"Tracking Pesanan\",\"text\":\"Pelanggan dapat memantau status pengiriman secara real-time.\",\"icon\":\"fa-solid fa-truck-fast\"},{\"title\":\"Layanan Pelanggan 24\\/7\",\"text\":\"Dukungan responsif untuk kebutuhan pre-sales dan after-sales.\",\"icon\":\"fa-solid fa-headset\"},{\"title\":\"Ketersediaan Stok Real-time\",\"text\":\"Informasi stok akurat dan transparan.\",\"icon\":\"fa-solid fa-boxes-stacked\"}],\"steps\":[{\"title\":\"Pendaftaran\",\"description\":\"Isi formulir pengajuan kemitraan melalui situs resmi kami.\"},{\"title\":\"Verifikasi\",\"description\":\"Tim kemitraan kami akan meninjau profil bisnis Anda.\"},{\"title\":\"Onboarding\",\"description\":\"Dapatkan akses ke dashboard partner dan resource teknologi.\"}],\"partner_url_rel\":\"noopener noreferrer nofollow\",\"partner_title\":\"\"}', '2026-02-23 07:51:02', '2026-02-23 08:28:25');
